        zenQuoteAuthor1 = "ਮਾ ਜਯਾ ਸਤੀ ਭਗਵਤੀ"
        zenQuote2 = "ਭਾਵਨਾਵਾਂ ਇੱਕ ਹਨੇਰੀ ਅਸਮਾਨ ਵਿੱਚ ਬੱਦਲਾਂ ਵਾਂਗ ਆਉਂਦੀਆਂ ਅਤੇ ਜਾਂਦੀਆਂ ਹਨ. ਚੇਤੰਨ ਸਾਹ ਮੇਰਾ ਲੰਗਰ ਹੈ।"
