        zenQuoteAuthor3 = "ਹਰਮਨ ਹੇਸੇ"
        zenQuote4 = "ਧਿਆਨ ਰੱਖਣਾ ਮੁਸ਼ਕਲ ਨਹੀਂ ਹੈ, ਸਾਨੂੰ ਇਸਨੂੰ ਕਰਨ ਲਈ ਯਾਦ ਰੱਖਣ ਦੀ ਲੋੜ ਹੈ।"
