val LocalAppStrings = staticCompositionLocalOf { EnglishStrings }

fun getLanguageStrings(code: String): AppStrings {
    return when (code) {
        "hi" -> HindiStrings
        "mr" -> MarathiStrings
        "es" -> SpanishStrings
        "fr" -> FrenchStrings
        "de" -> GermanStrings
        "ja" -> JapaneseStrings
        "ar" -> ArabicStrings
        "ru" -> RussianStrings
        "gu" -> GujaratiStrings
        "ta" -> TamilStrings
        "te" -> TeluguStrings
        "kn" -> KannadaStrings
        "bn" -> BengaliStrings
        "pa" -> PunjabiStrings
        "zh" -> ChineseStrings
        "pt" -> PortugueseStrings
        "it" -> ItalianStrings
        else -> EnglishStrings
    }
}